"""Public PHASA narrative: client challenge, approach, completed delivery and outcomes.
Source proposals and training materials remain private and are not bundled here.
"""

def build_story(t, p, heading, section, cards, bullets):
    title=t('PHASA: SEO, GEO e IA para marketing y ventas','PHASA: SEO, GEO and AI for marketing and sales')
    desc=t('Caso PHASA: estrategia B2B, SEO/GEO, buyer personas, funnel y campañas con IA. Equipos capacitados, HubSpot con Breeze, ChatGPT y Claude, automatizaciones y reportes.','PHASA case study: B2B strategy, SEO/GEO, buyer personas, funnel and AI-assisted campaigns. Trained teams, HubSpot with Breeze, ChatGPT and Claude, automation and reports.')
    hero=p('PHASA · Industria B2B · Proyecto culminado','PHASA · B2B industry · Completed project','eyebrow')
    hero+='<h1>PHASA.<br><span>'+t('SEO, GEO e IA para conectar marketing y ventas.','SEO, GEO and AI to connect marketing and sales.')+'</span></h1>'
    hero+=p('PHASA necesitaba conectar su posicionamiento digital con la operación comercial. Mood culminó una intervención que integró estrategia de marketing con IA, SEO/GEO, capacitación de los equipos y gestión de ventas en HubSpot con automatizaciones, reportes y seguimiento asistido por IA.','PHASA needed to connect digital visibility with sales operations. Mood completed a project integrating AI-assisted marketing strategy, SEO/GEO, team training and sales management in HubSpot with automation, reporting and AI-assisted follow-up.','lede')
    hero+='<div class="md-hero-actions"><a class="btn" href="#reto">'+t('Conocer el reto y la solución ↓','Explore the challenge and solution ↓')+'</a><a class="btn secondary" href="/contacto/" data-cta="phasa-hero">'+t('Hablemos de tu proyecto','Let’s discuss your project')+'</a></div><dl class="md-facts">'
    for a,b,c,d in [('Cliente','Client','PHASA','PHASA'),('Industria','Industry','Soluciones de hule · B2B','Rubber solutions · B2B'),('Mercado','Market','México','Mexico'),('Alcance','Scope','Marketing + SEO/GEO + IA + HubSpot','Marketing + SEO/GEO + AI + HubSpot')]:
        hero+='<div><dt>'+t(a,b)+'</dt><dd>'+t(c,d)+'</dd></div>'
    hero+='</dl><figure class="ph-cover"><img src="/assets/casos/phasa/project-cover.svg" width="1400" height="760" fetchpriority="high" alt="'+t('PHASA: estrategia digital, contenido, equipos y CRM conectados','PHASA: connected digital strategy, content, teams and CRM')+'"><figcaption>'+t('Estrategia, equipos y procesos conectados: la transformación de marketing y ventas entregada a PHASA.','Connected strategy, teams and processes: the marketing and sales transformation delivered to PHASA.')+'</figcaption></figure>'
    body='<article class="md-case ph-case"><section class="md-hero"><div class="wrap">'+hero+'</div></section><nav class="md-index" aria-label="'+t('Secciones del caso PHASA','PHASA case sections')+'"><div class="wrap">'
    for id,es,en in [('reto','El reto','The challenge'),('estrategia','La estrategia','The strategy'),('visibilidad','SEO y GEO','SEO and GEO'),('marketing','Marketing con IA','AI for marketing'),('crm','Ventas y HubSpot','Sales and HubSpot'),('automatizacion','Automatización','Automation'),('avance','Resultados','Results')]:
        body+=f'<a href="#{id}">'+t(es,en)+'</a>'
    body+='</div></nav>'

    challenge=heading('01 / El problema del cliente','Una empresa con experiencia. Una oportunidad de conectar su operación digital.','01 / The client’s challenge','An established business. An opportunity to connect its digital operations.')
    challenge+=p('PHASA es una empresa mexicana especializada en productos de hule y materiales para aplicaciones industriales. Contaba con un catálogo técnico, campañas activas, un equipo comercial con experiencia y HubSpot en operación. Su siguiente paso era aprovechar mejor esos recursos.','PHASA is a Mexican company specializing in rubber products and materials for industrial applications. It already had a technical catalog, active campaigns, an experienced sales team and HubSpot in use. Its next step was to make better use of those resources.')
    challenge+=p('El cliente planteó tres necesidades relacionadas: ganar visibilidad en Google y en las respuestas de herramientas de IA; reducir tareas manuales mediante inteligencia artificial; y fortalecer el uso del CRM para dar continuidad a cada oportunidad comercial.','The client identified three related needs: gain visibility on Google and in AI-generated answers; use artificial intelligence to reduce manual work; and make stronger use of its CRM to follow through on sales opportunities.')
    challenge+=cards([
        ('Posicionamiento por mejorar','Search visibility to strengthen','La auditoría encontró demanda orgánica y páginas con visibilidad, pero también oportunidades para mejorar los clics, organizar el contenido por intención de compra y explicar mejor las aplicaciones de los productos.','The audit found organic demand and pages already appearing in search, alongside opportunities to improve click-through, organize content around buying intent and explain product applications more clearly.'),
        ('Captación y ventas por conectar','Connect acquisition with sales','La medición mezclaba acciones de distinto valor. Hacía falta distinguir una visita o un clic de un lead válido, y relacionar la captación con el avance de las oportunidades en HubSpot.','Measurement combined actions of different business value. Visits and clicks needed to be distinguished from valid leads, and acquisition needed to be connected with deal progress in HubSpot.'),
        ('IA aplicada al trabajo diario','AI applied to daily work','Marketing y comercial necesitaban aprender a usar la IA sobre sus tareas reales: producir contenido técnico, analizar información, preparar seguimientos y mantener actualizado el CRM.','Marketing and sales needed practical AI skills for their work: producing technical content, analyzing information, preparing follow-ups and keeping the CRM up to date.')])
    body+=section('reto',challenge,True)

    strategy=heading('02 / El planteamiento de Mood','Trabajar la tecnología y la adopción del equipo al mismo tiempo.','02 / Mood’s approach','Develop the technology and team adoption together.')
    strategy+=p('Trabajamos en dos frentes conectados: una estrategia B2B para atraer al comprador adecuado y una operación comercial capaz de darle seguimiento. Identificamos buyer personas, necesidades, objeciones y criterios de decisión; definimos el funnel, los mensajes, las campañas y el plan de medios con apoyo de IA. En paralelo, capacitamos a marketing y comercial para aplicar esa estrategia y gestionar las oportunidades en HubSpot.','We worked on two connected fronts: a B2B strategy to attract the right buyers and a sales operation able to follow up. We identified buyer personas, needs, objections and decision criteria, then defined the funnel, messaging, campaigns and media plan with AI support. In parallel, we trained marketing and sales to apply the strategy and manage opportunities in HubSpot.')
    strategy+=cards([
        ('Diagnóstico y buyer personas','Diagnosis and buyer personas','Analizamos buscadores, analítica, campañas y CRM con IA para identificar demanda, perfiles de compra y puntos de fricción entre la captación y el seguimiento comercial.','We used AI to analyze search, analytics, campaigns and the CRM, identifying demand, buyer profiles and friction between acquisition and sales follow-up.'),
        ('Estrategia, funnel y campañas','Strategy, funnel and campaigns','Entregamos la estrategia, el funnel de conversión, la arquitectura SEO/GEO y el plan de medios, con audiencias, mensajes y contenidos por etapa. ChatGPT y Claude apoyaron el análisis, la planificación y la producción, con revisión del equipo.','We delivered the strategy, conversion funnel, SEO/GEO architecture and media plan, with audiences, messages and content for each stage. ChatGPT and Claude supported analysis, planning and production, with team review.'),
        ('Capacitación y automatización','Training and automation','Capacitamos a marketing y ventas e implementamos procesos de seguimiento, automatizaciones y reportes del pipeline. Cada oportunidad quedó asociada a una etapa, un responsable y una próxima acción.','We trained marketing and sales and implemented follow-up processes, automation and pipeline reports. Each opportunity was linked to a stage, an owner and a next action.')])
    strategy+='<blockquote class="md-pull">'+t('El resultado fue un recorrido comercial conectado: atraer al comprador, ayudarlo a elegir y dar continuidad a la oportunidad con datos e IA.','The result was a connected sales journey: attract buyers, help them choose and follow through on opportunities using data and AI.')+'</blockquote>'
    body+=section('estrategia',strategy)

    seo=heading('03 / La solución: posicionamiento','Convertir el conocimiento técnico en contenido que ayude a encontrar y elegir a PHASA.','03 / The solution: search visibility','Turn technical expertise into content that helps buyers find and choose PHASA.')
    seo+=p('Partimos de la auditoría de Google Analytics, Search Console y Google Ads. La lectura conjunta permitió identificar categorías con demanda y orientar la estrategia hacia las preguntas de compra del mercado industrial: qué material elegir, para qué aplicación sirve y qué características debe cumplir.','We started with an audit of Google Analytics, Search Console and Google Ads. Reviewing them together helped identify categories with demand and focus the strategy on industrial buying questions: which material to choose, what application it serves and which specifications matter.')
    seo+='<div class="md-pair"><div><h3>'+t('SEO: responder a la intención de búsqueda','SEO: address search intent')+'</h3>'+p('Organizamos la estrategia SEO por categorías, productos y aplicaciones. Entregamos páginas prioritarias, guías técnicas, títulos, descripciones y enlaces internos para acompañar al comprador desde su necesidad hasta la solicitud de cotización. La IA apoyó la investigación y la elaboración del contenido, con revisión técnica.','We organized the SEO strategy around categories, products and applications. We delivered priority pages, technical guides, titles, descriptions and internal links to support buyers from an initial need to a quote request. AI supported research and content development, with technical review.')+'</div><div><h3>'+t('GEO: facilitar la comprensión por la IA','GEO: make the information easier for AI to understand')+'</h3>'+p('Incorporamos criterios GEO al contenido: explicaciones directas, preguntas frecuentes, comparaciones de materiales y datos estructurados. Así, la información técnica quedó organizada para facilitar su comprensión tanto por compradores como por motores de respuesta con IA.','We incorporated GEO principles into the content: direct explanations, FAQs, material comparisons and structured data. Technical information was organized to make it easier for both buyers and AI answer engines to understand.')+'</div></div>'
    seo+=p('La entrega editorial incluyó una página de inicio, una página piloto, seis páginas de categoría y cinco guías, junto con preguntas frecuentes y lineamientos de publicación. PHASA recibió una estructura de contenidos coherente con sus productos, sus compradores y el funnel comercial.','The editorial delivery included a home page, a pilot page, six category pages and five guides, together with FAQs and publishing guidelines. PHASA received a content structure aligned with its products, buyers and sales funnel.')
    seo+=p('La medición se planteó con una lógica comercial: diferenciar interacciones de leads válidos y dar seguimiento al paso de lead a oportunidad y venta.','Measurement was designed around business outcomes: distinguish interactions from valid leads and track progress from lead to opportunity and sale.')
    body+=section('visibilidad',seo,True)

    marketing=heading('04 / La solución: equipo de marketing','Entrenar al equipo para producir, analizar y trabajar con IA.','04 / The solution: marketing team','Train the team to create, analyze and work with AI.')
    marketing+=p('La estrategia de posicionamiento necesitaba un equipo capaz de sostenerla. Por eso impartimos formación aplicada al contexto de PHASA, con sesiones, ejercicios y guías para utilizar IA en estrategia de contenido, análisis y tareas recurrentes.','The search strategy needed a team able to sustain it. We delivered training tailored to PHASA, using sessions, exercises and guides to apply AI to content strategy, analysis and recurring tasks.')
    marketing+=cards([
        ('Dar contexto antes de crear','Provide context before creating','El equipo trabajó con un brief de marca y buyer personas definidos. Con ChatGPT y Claude desarrolló mensajes, contenidos, propuestas de campaña y llamados a la acción según los problemas, objeciones y etapas de compra del cliente industrial.','The team worked with a brand brief and defined buyer personas. Using ChatGPT and Claude, it developed messages, content, campaign concepts and calls to action based on industrial buyers’ problems, objections and buying stages.'),
        ('Crear procesos reutilizables','Build repeatable processes','Con Claude y Cowork se enseñó a organizar documentos, crear instrucciones reutilizables —skills— y conectar herramientas. Las prácticas incluyeron auditorías, consulta de datos, planificación de campañas y gestión de archivos.','With Claude and Cowork, the team learned to organize documents, create reusable instructions—skills—and connect tools. Practice covered audits, data queries, campaign planning and file management.'),
        ('Analizar y revisar con criterio','Analyze and review critically','Se demostraron consultas de analítica e interpretación de comportamiento con Clarity. El entrenamiento incorporó revisión humana, validación técnica y permisos de acceso para usar la IA sobre información de trabajo.','Sessions demonstrated analytics queries and behavior analysis with Clarity. Training included human review, technical validation and access permissions for using AI with work information.')])
    marketing+=p('La capacitación dejó una metodología de trabajo reutilizable: contexto de marca → buyer persona → etapa del funnel → contenido, campaña o análisis → revisión → siguiente acción. El equipo recibió materiales y procesos para planificar marketing, desarrollar campañas y dar continuidad al plan de medios con IA.','Training established a repeatable method: brand context → buyer persona → funnel stage → content, campaign or analysis → review → next action. The team received materials and processes to plan marketing, develop campaigns and maintain the media plan with AI.')
    body+=section('marketing',marketing)

    sales=heading('05 / La solución: equipo comercial','HubSpot, Breeze, ChatGPT y Claude aplicados al pipeline de ventas.','05 / The solution: sales team','HubSpot, Breeze, ChatGPT and Claude applied to the sales pipeline.')
    sales+=p('PHASA ya utilizaba HubSpot. El reto era aprovecharlo mejor en el seguimiento cotidiano: mantener etapas y fechas útiles, registrar el contexto de las conversaciones y asegurar que cada oportunidad tuviera un responsable y una siguiente acción.','PHASA was already using HubSpot. The challenge was to make better use of it in daily follow-up: maintain useful stages and dates, record conversation context and ensure every opportunity has an owner and a next action.')
    sales+=p('Ordenamos el trabajo comercial en HubSpot y capacitamos a vendedores y responsables en el uso de Breeze —la IA de HubSpot—, ChatGPT y Claude. El equipo aprendió a consultar el CRM, resumir historiales, preparar seguimientos, revisar negocios detenidos y mantener el pipeline actualizado mediante accesos autorizados y revisión de los cambios.','We organized sales work in HubSpot and trained salespeople and managers to use Breeze—HubSpot’s AI—alongside ChatGPT and Claude. The team learned to query the CRM, summarize customer histories, prepare follow-ups, review stalled deals and keep the pipeline updated through authorized access and reviewed changes.')
    sales+='<h3 class="md-space">'+t('Del contacto al cierre: un proceso común','From contact to close: a shared process')+'</h3><ol class="ph-roadmap">'
    for n,es,en,desc_es,desc_en in [
        ('01','Contacto','Contact','Buscar y registrar al cliente sin duplicar información.','Find and record the customer without duplicating information.'),
        ('02','Oportunidad','Opportunity','Crear el negocio y asignar a la persona responsable.','Create the deal and assign an owner.'),
        ('03','Cotización','Quote','Registrar valor, referencia y una fecha de cierre realista.','Record the value, reference and a realistic close date.'),
        ('04','Seguimiento','Follow-up','Programar la siguiente tarea y guardar el contexto.','Schedule the next task and record the context.'),
        ('05','Cierre','Close','Actualizar el resultado y documentar el motivo de pérdida cuando corresponda.','Update the outcome and record the loss reason when applicable.')]:
        sales+='<li><span class="ph-step">'+n+'</span><div><h4>'+t(es,en)+'</h4>'+p(desc_es,desc_en)+'</div></li>'
    sales+='</ol>'+cards([
        ('IA para el vendedor','AI for salespeople','Un proceso de seguimiento asistido por IA para priorizar pendientes, localizar cotizaciones sin actividad, resumir el historial antes de una llamada y preparar mensajes con contexto. Las notas comerciales se transformaron en registros útiles para el CRM.','An AI-assisted follow-up process to prioritize tasks, find inactive quotes, summarize history before a call and prepare messages with context. Sales notes were turned into useful CRM records.'),
        ('IA para el gerente','AI for managers','Reportes automáticos y revisión del pipeline con IA para identificar oportunidades detenidas, analizar motivos de pérdida y definir acciones por vendedor a partir de los datos de HubSpot.','Automated reports and AI-assisted pipeline reviews to identify stalled opportunities, analyze loss reasons and define actions for each salesperson using HubSpot data.'),
        ('Equipo capacitado','Trained team','La formación incluyó guías, ejercicios y trabajo sobre procesos comerciales reales. El equipo incorporó una rutina común para consultar información, validar cambios y registrar la siguiente acción de cada negocio.','Training included guides, exercises and work on real sales processes. The team adopted a shared routine for reviewing information, validating changes and recording the next action for each deal.')])
    body+=section('crm',sales,True)

    automation=heading('06 / Automatización de procesos','Seguimiento y reportes automáticos, con responsables claros.','06 / Process automation','Automated follow-up and reporting, with clear ownership.')
    automation+=p('La implementación conectó la gestión del pipeline con tareas de seguimiento, alertas y reportes automáticos. La IA se incorporó al análisis de oportunidades y a la preparación de próximas acciones, mientras el equipo comercial mantuvo el control de las decisiones y la relación con el cliente.','The implementation connected pipeline management with follow-up tasks, alerts and automated reports. AI supported opportunity analysis and preparation of next actions, while the sales team retained control of decisions and customer relationships.')
    automation+='<div class="md-pair"><div><h3>'+t('Automatizaciones implementadas','Implemented automations')+'</h3>'+bullets([
        ('Tareas de seguimiento asociadas al envío de cotizaciones.','Follow-up tasks linked to sent quotes.'),
        ('Alertas sobre oportunidades sin actividad.','Alerts for inactive opportunities.'),
        ('Identificación de fechas de cierre vencidas para su revisión.','Identification of overdue close dates for review.'),
        ('Reportes automáticos del pipeline para la revisión comercial.','Automated pipeline reports for sales reviews.')])+'</div><div><h3>'+t('Seguimiento comercial con IA','AI-assisted sales follow-up')+'</h3>'+p('Breeze, ChatGPT y Claude apoyaron la lectura del historial, el análisis de negocios y la preparación de mensajes de seguimiento. Los responsables comerciales contaron con información organizada para decidir qué oportunidad atender, qué contexto recuperar y qué acción registrar en HubSpot.','Breeze, ChatGPT and Claude supported customer-history reviews, deal analysis and follow-up drafting. Sales owners had organized information to decide which opportunity to address, which context to retrieve and which action to record in HubSpot.')+'</div></div>'
    automation+=p('PHASA cerró el proyecto con procesos comerciales definidos, automatizaciones implementadas y equipos capacitados para utilizarlos. Marketing y ventas compartieron una misma lógica de trabajo: contexto del comprador, registro en CRM, siguiente acción y revisión de resultados con IA.','PHASA completed the project with defined sales processes, implemented automation and teams trained to use them. Marketing and sales shared a common working method: buyer context, CRM records, next actions and AI-assisted performance reviews.')
    body+=section('automatizacion',automation)

    progress=heading('07 / Resultados del proyecto','Marketing y ventas conectados. Una operación con IA en marcha.','07 / Project results','Connected marketing and sales. AI-enabled operations in place.')
    progress+=p('El proyecto culminó con una estrategia B2B definida, una entrega de contenido SEO/GEO alineada al comprador y una operación comercial organizada en HubSpot. El resultado fue una forma de trabajo común entre marketing y ventas, respaldada por capacitación, automatizaciones, reportes y seguimiento con IA.','The project concluded with a defined B2B strategy, buyer-focused SEO/GEO content and organized sales operations in HubSpot. The result was a shared way of working across marketing and sales, supported by training, automation, reporting and AI-assisted follow-up.')
    progress+=cards([
        ('Marketing con dirección comercial','Marketing aligned with sales','Buyer personas identificados, funnel definido, estrategia SEO/GEO, campañas y plan de medios desarrollados con IA. Los contenidos y mensajes quedaron alineados con las necesidades y etapas de decisión del comprador industrial.','Identified buyer personas, a defined funnel, SEO/GEO strategy, campaigns and a media plan developed with AI. Content and messaging were aligned with industrial buyers’ needs and decision stages.'),
        ('Dos equipos capacitados en IA','Two teams trained in AI','Marketing incorporó ChatGPT y Claude a la planificación, el contenido y el análisis. Comercial incorporó Breeze, ChatGPT y Claude al uso de HubSpot, la revisión del pipeline y el seguimiento de oportunidades.','Marketing incorporated ChatGPT and Claude into planning, content and analysis. Sales incorporated Breeze, ChatGPT and Claude into HubSpot workflows, pipeline reviews and opportunity follow-up.'),
        ('Gestión comercial automatizada','Automated sales management','Pipeline organizado, tareas y alertas de seguimiento, reportes automáticos y análisis con IA. El equipo contó con una visión compartida de las oportunidades y de las acciones necesarias para atenderlas.','An organized pipeline, follow-up tasks and alerts, automated reports and AI-assisted analysis. The team gained a shared view of opportunities and the actions needed to address them.')])
    progress+=p('Proyecto culminado · Caso actualizado el 25 de noviembre de 2026. Los resultados presentados corresponden a la estrategia, los entregables, la capacitación y los procesos implementados. No se atribuyen porcentajes de crecimiento en ventas o posicionamiento sin una medición comparable.','Completed project · Case updated November 25, 2026. Results describe the strategy, deliverables, training and implemented processes. No sales or search growth percentages are claimed without comparable measurement.','note')
    body+=section('avance',progress,True)
    close=heading('Marketing + ventas + tecnología','¿Tu empresa necesita conectar estos mismos procesos?','Marketing + sales + technology','Does your business need to connect these processes?')
    close+=p('Podemos ayudarte a identificar dónde se pierde continuidad entre la captación y la venta, qué necesita aprender tu equipo y qué procesos conviene automatizar con IA.','We can help identify gaps between acquisition and sales, the skills your team needs and the processes worth automating with AI.')
    close+='<div class="actions"><a class="btn" href="/contacto/" data-cta="phasa-closing">'+t('Conversemos sobre tu empresa','Let’s discuss your business')+'</a><a class="btn secondary" href="https://www.phasa.mx/" target="_blank" rel="noopener noreferrer">'+t('Visitar PHASA ↗','Visit PHASA ↗')+'</a></div>'
    body+=section('contactar',close)+'</article>'
    return body,title,desc
